  def generate_index_sql(self) -> (string, error):
    if self == None or self.indices == None:
      return ("", errors.new("Index SQL generator: Cannot pass null parameter"))
    sql = nil
    tmp_sql = nil
    length = len(self.indices)
    if length > 0:
      for index, ik in self.indices:
        u_name = nil
        u_cols = nil
        for col_index, col_name in ik.column_names:
          if col_index == 0:
            u_name = col_name
            u_cols = "`" + col_name + "`"
          else:
            u_name = u_name + "_" + col_name
            u_cols = u_cols + ",`" + col_name + "`"
        tmp_sql = "KEY `{u_name}` ({u_cols})"
        if index == 0:
          sql = tmp_sql
        else:
          sql = sql + ",\n" + tmp_sql
    else:
      sql = ""
    return (sql, None)
