def create_bridge_network(bridge_name: Str, bridge_address: Str):
  (_, err) = net.interface_by_name(bridge_name)
  if err == None:
    return
  if not strings.contains(err.error(), "no such network interface"):
    panic(err)
  link_attrs = NetlinkLinkAttrs { name: bridge_name, tx_q_len: -1 }
  bridge = NetlinkBridge { link_attrs: *link_attrs }
  commons.must(netlink.link_add(bridge))
  (address, err) = netlink.parse_addr(bridge_address)
  commons.must(err)
  commons.must(netlink.addr_add(bridge, address))
  commons.must(netlink.link_set_up(bridge))
def delete_bridge_network(bridge_name: Str):
  (_, err) = net.interface_by_name(bridge_name)
  if err != None and not strings.contains(err.error(), "no such network interface"):
    panic(err)
  link_attrs = NetlinkLinkAttrs { name: bridge_name, tx_q_len: -1 }
  bridge = NetlinkBridge { link_attrs: *link_attrs }
  commons.must(netlink.link_del(bridge))
